
<?php $__env->startSection('title', 'Schedule audit – '.$event->name); ?>
<?php $__env->startSection('content'); ?>
<div class="container-xxl py-3">
  <div class="d-flex flex-wrap justify-content-between gap-3 mb-3"><div><h3>Schedule audit</h3><p class="text-muted mb-0"><?php echo e($event->name); ?> · <?php echo e($scope['date'] === 'all' ? 'All saved days' : \Carbon\Carbon::parse($scope['date'])->format('D j M Y')); ?><?php echo e(!empty($scope['draw_id']) ? ' · Selected draw' : ' · All draws'); ?><?php echo e(!empty($scope['venue_id']) ? ' · Selected venue' : ' · All venues'); ?></p></div><a class="btn btn-outline-primary" href="<?php echo e(route('backend.event-venue-schedule.calendar', ['event'=>$event->id]+$scope)); ?>">Back to saved schedule</a></div>
