  <div class="card card-body mb-3"><div class="d-flex flex-wrap gap-4"><strong><?php echo e($report['checked']); ?> saved matches checked in this view</strong><span class="text-danger"><?php echo e($report['errors']); ?> errors</span><span class="text-warning"><?php echo e($report['warnings']); ?> warnings</span></div><p class="small text-muted mt-2 mb-0"><?php echo e($report['compared_event_matches']); ?> event bookings compared · <?php echo e($report['external_bookings']); ?> nearby outside-event bookings compared · Rest <?php echo e($report['rest_minutes']); ?> minutes · Court turnaround <?php echo e($report['court_gap_minutes']); ?> minutes.</p></div>
